"""Eight additional original strategic decision cases. Loaded by build-cases.py."""
case('sube-lokasyonu','Yeni şube: hangi lokasyon, neden?',2,'Stratejik karar',50,['lead','analyst','operations','custom'],['Lokasyon seçimi','Satış aktarımı','Duyarlılık'],
'Pera Yaşam, aynı şehirde ikinci şubesini açmak istiyor. Üç lokasyonun ziyaretçi tahmini, kira ve açılış giderleri farklı. Satış müdürü B’yi, operasyon C’yi öneriyor. Yönetim kuruluna bir lokasyon seçimi ya da gerekçeli erteleme önerisi sunacaksın.',
'Aylık şube faaliyet sonucunu ve mevcut şubeden kayacak satışın şirket toplamına etkisini ayır. Yüksek ziyaretçi veya en düşük kira tek başına karar olmasın. Bir öneri seç; hangi koşulda fikrini değiştireceğini açıkla.',[
 doc('Aday lokasyonlar','Aylık satış = ziyaretçi × dönüşüm × sepet. Brüt marj ürün değişken maliyeti sonrasıdır. Faaliyet sonucu = satış × marj − aylık sabit gider. Açılış yatırımı tek seferlik nakit çıkışıdır; aylık gider değildir. Vergi, finansman ve amortisman dahil değildir.',['Lokasyon','Ziyaretçi/ay','Dönüşüm %','Sepet TL','Brüt marj %','Sabit gider TL/ay','Açılış yatırımı TL'],[['A / Merkez AVM',24000,8,800,35,400000,4800000],['B / Ana cadde',18000,10,900,38,330000,3200000],['C / Gelişen mahalle',14000,12,850,40,300000,2600000]]),
 doc('Mevcut şube etkisi','Yeni şube satışının aşağıdaki kısmının mevcut şubeden kayacağı tahmin ediliyor. Kaybolan satışın eski şubedeki katkı oranı ayrıca verilmiştir. Eski şubenin sabit gideri azalmıyor. Şirket ek faaliyet katkısı = yeni şube faaliyet sonucu − eski şubede kaybolan katkı. Bu tahminler pilotla doğrulanmadı.',['Lokasyon','Mevcut şubeden kayacak yeni satış payı %','Kaybolan satışın eski katkı oranı %'],[['A / Merkez AVM',0,35],['B / Ana cadde',20,38],['C / Gelişen mahalle',5,40]]),
 doc('Nakit ve saha kısıtları','Bu proje için ayrılmış nakit 8.000.000 TL; açılış yatırımı sonrasında en az2.000.000 TL rezerv korunmalı. Ek işletme sermayesi gereği henüz ölçülmedi. A için beş yıllık kira taahhüdü, B için yaya erişimi ve yükleme saatleri, C için belediye erişim düzenlemesinin tamamlanması araştırılmalı. Başvuru/izin süresi kesin değil. Ziyaretçiler aynı sayım yöntemiyle tahmin edilmiştir; bunlar gerçekleşmiş satış değildir.')],
 ['Üç seçeneğin aylık satışını ve faaliyet sonucunu hesapla. Mevcut şubeye etkisini ayrıca göster.','Açılış yatırımı sonrası rezerv kontrolü yap; bilinmeyen işletme sermayesini nasıl ele alacağını belirt.','Finansal katkı, müşteri erişimi, sözleşme esnekliği ve uygulama riskini içeren bir karar tablosu kur. Ağırlık kullanırsan gerekçesini yaz.','Hangi lokasyonu önerdiğini veya neden ertelediğini açıkla. Diğer iki seçeneğin neden geride kaldığını somutlaştır.','Beş slaytlık yönetim kurulu sunumu iskeleti ve karar öncesi saha doğrulama planı hazırla.'],[
 num('b_sube','B lokasyonunun aylık şube faaliyet sonucu',285600,'TL/ay',.1,'18.000×0,10×900=1.620.000 satış;×0,38−330.000=285.600.'),num('b_grup','B lokasyonunun şirkete ek faaliyet katkısı',162480,'TL/ay',.1,'285.600−(1.620.000×0,20×0,38)=162.480.'),num('c_grup','C lokasyonunun şirkete ek faaliyet katkısı',242640,'TL/ay',.1,'14.000×0,12×850=1.428.000; şube sonucu 271.200; eski katkı kaybı 28.560; ek katkı 242.640.'),num('a_nakit','A yatırımı sonrasında kalan proje nakdi',3200000,'TL',.1,'8.000.000−4.800.000=3.200.000.2 milyon rezerv koşulunu ilk yatırım aşamasında sağlar; işletme sermayesi henüz dahil değildir.')],
 [criterion('Şube ve şirket ayrımı','Yeni şube kârını eski şubenin katkı kaybıyla birlikte inceler; aktarılan satışın tamamını kâr kaybı saymaz.'),criterion('Sermaye ve rezerv','Tek seferlik yatırımı aylık sonuca karıştırmaz; işletme sermayesinin eksik olduğunu açıklar.'),criterion('Stratejik ölçütler','Müşteri, erişim, kira esnekliği ve açılış riskini gerekçeli ölçütlerle karşılaştırır.'),criterion('Koşullu öneri','Bir seçenek önerir; alternatiflerin üstün yanlarını ve fikrini değiştirecek koşulu da açıklar.'),criterion('Doğrulama','Ziyaretçi/dönüşüm/aktarım tahminlerini ve izin durumunu sahada sınayacak plan kurar.')],
 {'title':'C’de dönüşüm beklentisi düştü','text':'Saha denemesi C’nin dönüşümünü%12 yerine%9 olarak güncelledi. Diğer tahminler aynı; kayma payı yine yeni şube satışının%5’i. Şirket ek katkısı nasıl değişir? İlk önerini korur musun?','reference':'C satış 1.071.000; şube sonucu 128.400; eski katkı kaybı 21.420; ek katkı 106.980 TL/ay. A137.600 ve B162.480 TL/ayla finansal sıralama değişir. İzin, rezerv ve stratejik hedefleri yeniden ele al; C’yi sırf önce onu savundun diye koruma.'},
 ['A satış 1.536.000 ve faaliyet/ek katkı 137.600 TL. B şube 285.600 ile önde görünür; şirket ek katkısı 162.480’e iner. C şube 271.200, şirket ek katkısı 242.640 TL.','İlk tahminlerde C şirket katkısı ve daha düşük yatırım açısından güçlüdür. Bu, izin ve dönüşüm belirsizliğini ortadan kaldırmaz. B daha güçlü bağımsız şube sonucuna rağmen eski satış aktarımı nedeniyle toplamda geride kalır.','A/B/C yatırım sonrası nakit 3,2/4,8/5,4 milyon TL. Yalnız bu hesap açılışın bütün nakit ihtiyacını kapsamaz. Koşullu öneri, saha verisi ve onay kapılarıyla savunulmalıdır.'],
 ['Yalnız ziyaretçi sayısına veya kiraya göre seçim yapmak.','B’deki mevcut satış aktarımını yok saymak veya kaybolan ciroyu doğrudan kâr kaybı saymak.','Açılış yatırımını hem aylık gider hem başlangıç nakdi olarak çift saymak.'],['C için hangi dönüşüm oranının altında B’yi yeniden değerlendirirsin?','Daha düşük kısa vadeli katkıyı stratejik erişim için seçersen bunu nasıl doğrularsın?'])
case('buyume-formati','Yeni pazara giriş: şube, bayilik, çevrim içi?',2,'Stratejik karar',45,['lead','analyst','custom'],['Büyüme modeli','Likidite','Geri döndürülebilirlik'],
'Kuzey Tasarım, yeni bir şehirde büyümek istiyor. Kendi mağazası marka kontrolü, bayilik düşük başlangıç gideri, çevrim içi pilot ise öğrenme esnekliği sunuyor. Aynı sermayeyle hepsini başlatamazsın.',
'İlk üç aylık nakdi ve operasyon sonucunu ayrı göster. Veriler kurgusal; marka kontrolü ve müşteri deneyimi sayısal puana otomatik indirgenmez. Başlamak kadar denemek veya ertelemek de gerekçeli seçenek olabilir.',[
 doc('İlk üç ayın planı','Katkı, ürün ve kanala bağlı değişken giderler sonrası; sabit işletme gideri ve tek seferlik başlangıç yatırımı öncesidir. Bayilikte tutarlar bayinin cirosu değil, şirketin net katkısıdır. Tüm işletme gelir/gideri aynı ay nakde dönüşür varsayımı kullanılıyor.',['Model','Başlangıç nakdi TL','Ay1 katkı TL','Ay2 katkı TL','Ay3 katkı TL','Aylık sabit gider TL'],[['Kendi şubesi',1800000,90000,140000,180000,120000],['Bayilik',600000,70000,70000,70000,20000],['Çevrim içi pilot',400000,100000,130000,160000,120000]]),
 doc('Sermaye sınırı','Başlangıç nakdi 2.000.000 TL ve her ay sonu en az400.000 TL korunmalı. Başlangıç yatırımı faaliyetten önce ödenir; o anda da rezerv korunmalı. Ek finansman onayı yok. Pilotun sonunda kapatma/çıkış maliyeti verilmedi.'),
 doc('Model farkları','Kendi şubesinde deneyim kontrolü yüksek; kira ve ekip taahhüdü uzun. Bayilikte yerel işletmecinin hizmet standardı ve sözleşme yetkileri doğrulanmalı. Çevrim içi pilotta müşteri edinme ve iade varsayımları henüz gerçek veriyle sınanmadı. İlk üç aydan sonraki hacim ve kârlılık tahmin edilmedi.')],
 ['Her model için üç aylık faaliyet sonucunu ve yatırım dahil ay sonu nakitlerini hesapla.','Rezerv koşulunu ihlal eden modeli belirle; muhasebesel sonuçla nakit kısıtını ayır.','Kontrol, öğrenme hızı, geri döndürülebilirlik ve kapasiteyi içeren karşılaştırma yap.','Bir başlangıç modeli veya aşamalı yol öner; neden diğerlerinden başlamadığını açıkla.','90 gün sonunda devam/ölçekleme/durdurma kararında kullanacağın kanıtları ve sınırları yaz.'],[
 num('sube','Kendi şubesinin üç aylık faaliyet sonucu',50000,'TL',.1,'(90.000−120.000)+(140.000−120.000)+(180.000−120.000)=50.000.'),num('ilk_nakit','Kendi şubesinde ilk ay sonu nakit',170000,'TL',.1,'2.000.000−1.800.000−30.000=170.000; başlangıçta kalan 200.000 de400.000 rezervin altındadır.'),num('bayi','Bayilikte üçüncü ay sonu nakit',1550000,'TL',.1,'2.000.000−600.000+3×(70.000−20.000)=1.550.000.')],
 [criterion('Faaliyet ve yatırım','Tek seferlik yatırımı üç aylık faaliyet sonucundan ayırır; nakit hesabında dahil eder.'),criterion('Zorunlu kısıt','Şubenin rezerv ihlalini olumlu üçüncü ay sonucu ile gizlemez.'),criterion('Model karşılaştırması','Kontrol, yerel ortak, müşteri öğrenmesi ve çıkış esnekliğini açıklar.'),criterion('Aşamalı öneri','Sermaye/insan kaynağıyla tutarlı bir ilk adım ve sonraki kapı önerir.'),criterion('Başarı kanıtı','İlk üç ayı uzun vadeli başarı garantisi saymaz; devam/durdurma koşullarını tanımlar.')],
 {'title':'Bayilikte kontrol şartı','text':'Bayi, şirketin kalite denetimine yalnız yılda bir izin vereceğini ve müşteri şikâyet verisini paylaşmayacağını söylüyor. Finansal tahminler değişmiyor. Önerini hangi şartlarla sürdürür veya değiştirirsin?','reference':'Bu bilgi gelir hesabını değiştirmese de marka/hizmet riskini ve izlenebilirliği değiştirir. Denetim, veri paylaşımı ve düzeltme yükümlülükleri için yetkili sözleşme müzakeresi gerekir. Bu koşullar sağlanmıyorsa çevrim içi pilot veya erteleme savunulabilir; sırf nakit yüksek diye onaysız sözleşme önerilmez.'},
 ['Kendi şubesinde aylık faaliyet−30.000/+20.000/+60.000 TL; üçüncü ay nakit 250.000 TL. Başlangıçtan itibaren rezerv ihlal edilir.','Bayilik aylık 50.000 TL, üç aylık 150.000 TL faaliyet sonucu ve ay3 nakit 1.550.000 TL. Çevrim içi pilot−20.000/+10.000/+40.000, toplam 30.000 TL; ay3 nakit 1.630.000 TL.','Bayilik güçlü kısa vadeli sonuç, pilot yüksek geri dönme/öğrenme esnekliği sunabilir. Ortak ve veri koşulları doğrulanmadan tek evrensel doğru seçenek yoktur.'],
 ['Yatırımı dışarıda bırakıp tüm modellerin nakit rezervini koruduğunu söylemek.','Bayinin cirosu ile şirketin bayilik katkısını karıştırmak.','Üç aylık tahminden yıllık kesin kazanç çıkarmak.'],['Pilotta öğrendiğin hangi veri mağaza kararını değiştirebilir?','Rezerv kuralı kaldırılırsa kendi şubesini otomatik seçer misin?'])
case('nakit-toparlanma','Şirket zor durumda: ilk dört haftayı çıkar',3,'Stratejik karar',60,['lead','analyst','operations','custom'],['Nakit planlama','Aksiyon sırası','Kriz koordinasyonu'],
'Bir hizmet şirketinin bilançosunda alacak ve stok var; buna rağmen iki hafta içinde ödeme sıkışıklığı bekleniyor. Yönetim “önce satışları artıralım” diyor. İlk dört haftalık nakit korunma ve toparlanma planını hazırlayacaksın.',
'Borçlanma veya ödeme erteleme onayı verilmiş gibi davranma; aşağıdaki seçeneklerin karşı taraf/finans onayına bağlı olduğunu belirt. Bu bir sentetik yönetim vakasıdır. Çalışan, müşteri ve operasyon yükümlülükleri için yetkili ekiplerle birlikte hareket et.',[
 doc('Baz haftalık nakit planı','Başlangıç nakdi 300.000 TL. Akımlar hafta sonunda netlenir; hafta içi gün bazlı sıralama ayrıca doğrulanmalı. Alacak/stok toplamları bu tablonun üstüne nakit olarak eklenmez.',['Hafta','Tahsilat TL','Ödeme TL'],[['1',200000,450000],['2',250000,550000],['3',500000,400000],['4',450000,350000]]),
 doc('Görüşülebilen aksiyonlar','1) Üçüncü haftada beklenen tahsilatın 200.000 TL’si ikinci haftaya alınabilir; toplam tahsilat artmaz. 2) İkinci haftanın 300.000 TL tedarikçi ödemesi dördüncü haftaya kayabilir; toplam ödeme azalmaz. 3) Finans onaylarsa ilk haftanın başında en fazla 200.000 TL geçici kaynak sağlanabilir; geri ödeme 8. haftada, bu ufkun dışında. Faiz/gider bu basitleştirilmiş tabloda yok, son karar için ayrıca gerekir.'),
 doc('Yönetim bilgisi','Her hafta sonunda en az100.000 TL tampon hedefleniyor. Bilançoda 2.000.000 TL alacak, 3.000.000 TL stok bulunması bunların hemen nakit olduğu anlamına gelmiyor. Yeni satışın tahsilat süresi henüz bilinmiyor. Tedarikçi ertelemesinin kritik hizmeti kesip kesmeyeceği doğrulanmalı.')],
 ['Baz senaryoda her hafta sonu nakdi, en düşük noktayı ve100.000 TL tampon için gereken başlangıç desteğini hesapla.','Erken tahsilat ile ödeme ertelemesini birlikte uygula; çift saymadan yeni planı çıkar.','Geçici kaynak üst sınırıyla tampon hedefinin hangi aksiyon birleşiminde sağlanabileceğini göster.','İlk48 saat için sorumlu, onay, teyit zamanı ve başarısız olursa alternatif içeren aksiyon tablosu yaz.','Satış, stok ve alacak için 30 günlük ek inceleme öner; nakit korunmasıyla kalıcı kârlılığı ayır.'],[
 num('dip','Baz senaryodaki en düşük hafta sonu nakit',-250000,'TL',.1,'Hafta sonları 50.000,−250.000,−150.000,−50.000 TL; dip ikinci haftada.'),num('baz_destek','Baz senaryoda 100.000 tampon için gereken başlangıç desteği',350000,'TL',.1,'100.000−(−250.000)=350.000;200.000 üst sınır tek başına yetmez.'),num('birlesik','İki zamanlama aksiyonu sonrası dördüncü hafta nakdi, desteksiz',-50000,'TL',.1,'Erken tahsilat/erteleme sonrası 50.000,250.000,150.000,−50.000. Ufuk toplamı değişmediği için son nakit değişmez.'),num('ek_destek','İki zamanlama aksiyonuyla 100.000 tamponu koruyan asgari destek',150000,'TL',.1,'Yeni dip−50.000;100.000 tampon için 150.000 başlangıç desteği. Hafta sonları 200.000,400.000,300.000,100.000 olur.')],
 [criterion('Nakit bütünlüğü','Haftalık bakiyeyi önceki haftadan devreder; alacağı/stoku nakit diye eklemez.'),criterion('Zamanlama ve tutar','Erken tahsilatı ve ertelenen ödemeyi iki haftada karşılıklı işler; kalıcı kazanç saymaz.'),criterion('Uygulanabilir birleşim','200.000 finansman sınırını ve100.000 tamponu birlikte denetler.'),criterion('Öncelik ve yetki','48 saatlik teyit/onay akışını ve kritik operasyon etkisini tanımlar.'),criterion('Kalıcı toparlanma','Dört haftayı kurtarmanın zarar modelini çözmediğini açıklar.'),criterion('Belirsizlik planı','Tahsilat ve tedarikçi onayı gerçekleşmezse tetiklenecek alternatifleri belirtir.')],
 {'title':'Tahsilat gecikmesi','text':'Üçüncü haftada, erken tahsil edilen 200.000 TL dışındaki tahsilatın 200.000 TL’si beşinci haftaya kaldı. Diğer aksiyonlar aynı. Tamponu korumak için toplam geçici kaynak ihtiyacı ne olur; 200.000 TL tavan yeter mi?','reference':'Zamanlama aksiyonları sonrası desteksiz bakiyeler 50.000,250.000,−50.000,−250.000 TL olur. 100.000 tampon için 350.000 toplam destek gerekir; 200.000 tavanın 150.000 üzerindedir. Ek doğrulanmış tahsilat, uygun gider/taahhüt değişimi veya yetkili farklı kaynak gerekir; ödemeleri sessizce durdurmak plan değildir.'},
 ['Baznakit 50.000/−250.000/−150.000/−50.000. Dip−250.000; tamponlu gereksinim 350.000 TL.','İki zamanlama aksiyonu 50.000/250.000/150.000/−50.000 yapar. Toplam nakit açığı bitmez; 150.000 onaylı ek kaynakla tampon korunur.','Önce günlük nakit görünürlüğü, tahsilat/erteleme teyidi, kaynak onayı ve kritik hizmet etkisi. Sonraki 30 günde marj, stok dönüşü, alacak vadesi ve taahhütler incelenir. Yeni satışın nakdi ne zaman getirdiği bilinmeden çözüm sayılmaz.'],
 ['300.000 TL ertelemeyi kalıcı maliyet tasarrufu saymak.','Erken tahsilatı ikinci haftaya ekleyip üçüncü haftadan düşmemek.','Stok 3 milyon diye nakit açığı olmadığını söylemek.'],['Hafta içindeki ödeme sırası hafta sonu planını neden yetersiz bırakabilir?','Zarardaki şirkette satış büyümesi hangi koşulda nakit sorununu artırır?'])
case('zarar-portfoyu','Zarar eden işi kapatmak her zaman çözüm mü?',3,'Stratejik karar',60,['lead','analyst','custom'],['Katkı analizi','Kaçınılabilir maliyet','Portföy kararı'],
'Bir şirketin üç ürün hattından ikisi dağıtılmış gider sonrası zararda görünüyor. Yönetim ikisini de kapatmayı düşünüyor. Hangi işin gerçekten katkı sağladığını ve hangi maliyetin kapanınca ortadan kalkacağını inceleyeceksin.',
'Dağıtılmış genel gider ile kaçınılabilir doğrudan gideri ayır. Kapatma, fiyat/ürün değişimi, küçültme veya sürdürmeyi karşılaştır. Sadece en düşük raporlanmış kârı olan işi kapatma.',[
 doc('Aylık ürün hattı tablosu','Doğrudan sabit gider, hat kapanırsa 30 gün sonra tamamen ortadan kalkabilecek tutardır. Aylık merkez gideri toplam 300.000 TL; hatlara eşit 100.000 dağıtılmıştır ve kapanışla otomatik azalmaz.',['Hat','Satış TL','Değişken gider TL','Kaçınılabilir doğrudan sabit gider TL','Dağıtılmış merkez gideri TL'],[['A',1200000,840000,180000,100000],['B',800000,560000,200000,100000],['C',500000,400000,140000,100000]]),
 doc('Kapatma etkileri','C’nin kapatılması A’da aylık 80.000 TL satış kaybettirebilir; A’nın bu satıştaki katkı oranı%30, A sabit gideri değişmez. C’nin tek seferlik kapanış gideri 50.000 TL. B kapanışının başka satışa etkisi veya kapanış gideri bu karşılaştırmada sıfır varsayılmıştır; sözleşmelerle ayrıca doğrulanmalı.'),
 doc('C için alternatif','C fiyatı%10 artırırsa hacmin%20 düşeceği varsayılıyor. Değişken gider hacimle orantılı, doğrudan sabit gider değişmiyor. Bu seçenek A satışını etkilemiyor varsayımı kullanılıyor. Talep tepkisi henüz pilotla doğrulanmadı. Merkez gideri için somut azaltım onayı yok.')],
 ['Hat bazında katkıyı, doğrudan sonucu ve dağıtım sonrası sonucu hesapla; şirket toplamına bağla.','B kapanırsa şirket sonucunun nasıl değiştiğini göster.','C kapanışını ilk geçiş dönemi giderinden ayrı, sürekli durum etkisiyle değerlendir; A satışını dahil et.','C fiyat değişimi alternatifini hesapla; kapanışla kıyasla ve tahmin riskini açıkla.','Bir portföy önerisi ve30/60 günlük doğrulama planı hazırla; hâlâ kalan zararı görünür tut.'],[
 num('b_katki','B hattının aylık katkısı, doğrudan sabit gider öncesi',240000,'TL',.1,'800.000−560.000=240.000; doğrudan sabit sonrası 40.000; merkez dağıtımı sonrası−60.000.'),num('toplam','Mevcut şirket aylık faaliyet sonucu',-120000,'TL',.1,'A180.000+B40.000+C(−40.000)−300.000=−120.000.'),num('b_kapat','Yalnız B kapandıktan sonraki sürekli şirket sonucu',-160000,'TL',.1,'B’nin 40.000 net doğrudan katkısı kaybolur; merkez gideri kalır.−120.000−40.000=−160.000.'),num('c_kapat','Yalnız C kapandıktan sonraki sürekli şirket sonucu',-104000,'TL',.1,'C kapanışı 140.000 sabit tasarruf−100.000 kayıp katkı−24.000 A katkı kaybı=16.000 iyileşme;−104.000 sonuç. Tek seferlik 50.000 ayrıca.')],
 [criterion('Maliyet ayrımı','Katkı, kaçınılabilir sabit ve dağıtılmış merkez giderini ayrı hesaplar.'),criterion('Toplam şirket etkisi','Bir hattın zararlı görünmesini şirket toplamını iyileştiren kapanışla karıştırmaz.'),criterion('Bağlantılı satış','C’nin A satışına etkisini katkı oranıyla işler; kaybolan cironun tümünü kâr kaybı saymaz.'),criterion('Geçiş ve sürekli durum','30 günlük gider kalkışını, 50.000 tek seferlik gideri ve sürekli sonucu ayrı gösterir.'),criterion('Alternatif ve kanıt','Fiyat/hacim varsayımını sınamayı önerir; iyileşmenin zararı tamamen çözmediğini saklamaz.'),criterion('Uygulama','Ürün, müşteri ve ekip geçişini sahip/tarih/karar kapısıyla planlar.')],
 {'title':'Merkez gideri önerisi','text':'Yönetim üç ay sonra 60.000 TL aylık merkez gideri azaltabilecek bir plan önerdi; henüz onaylı değil. B’yi kapatmaya gerekçe olarak bu tasarrufu yalnız B’ye yazabilir misin? İlk ay nakdi ile dördüncü ay sonucunu nasıl ayırırsın?','reference':'Bağımsız merkez tasarrufu B kapanışının doğrudan faydası gibi yazılmaz; hangi karara bağlı olduğu doğrulanır. B’yi koruyup merkez giderini azaltma da karşılaştırılmalı. Üç ay sonra başlayacak fayda ilk ayın nakdine eklenemez.'},
 ['Dağıtım sonrası A80.000/B−60.000/C−140.000 TL; toplam−120.000. B merkez giderini taşımaya 40.000 TL katkı verir. Kapanışı sonucu−160.000 yapar.','C kapanışı sürekli durumda 16.000 TL iyileştirir, şirket hâlâ−104.000 TL’dedir; geçiş maliyeti ve giderin kalkacağı tarih ayrı önemlidir.','C fiyat seçeneği satış 440.000, değişken 320.000, doğrudan sabit 140.000 →−20.000 doğrudan sonuç; bazdan 20.000 iyileşme ile şirket−100.000. Tahminler tutarsa kapanıştan biraz iyi; müşteri tepkisi doğrulanmalıdır.'],
 ['Dağıtılmış merkez giderinin kapanışla yok olacağını varsaymak.','B’nin−60.000 raporlanmış zararını kapanış tasarrufu saymak.','C kapanışının A etkisini veya geçiş zamanını yok saymak.'],['Kaçınılabilir diye etiketlenen sabit gideri nasıl doğrularsın?','Fiyat artışı sonrası hacim yalnız%10 düşerse C için görüşün nasıl değişir?'])
case('doksan-gun-toparlanma','Şirketi 90 günde toparla: önce hangi aksiyonlar?',3,'Stratejik karar',65,['lead','analyst','operations','custom'],['Stratejik öncelik','Kaynak kısıtı','30/60/90 planı'],
'Dora Hizmet’in satışları yüksek ama şirket her ay zarar ediyor. Yönetim fiyat artışı, tedarikçi pazarlığı, kalite, stok ve büyük bir sistem yatırımı arasında bölünmüş. İlk30 günün kaynakları sınırlı; 90 günlük bir yol çizmen bekleniyor.',
'Aşağıdaki faydalar tahmindir; tam uygulama sonrası aylık etkiyi gösterir, ilk ayın otomatik gerçekleşmesi değildir. Kalıcı kârlılık, tek seferlik nakit ve gelecekteki öğrenme faydasını ayır. Her aksiyonu aynı anda başlatma.',[
 doc('Aylık baz','Satış 10.000.000 TL, değişken gider 7.000.000 TL, sabit gider 3.400.000 TL. Ürün/hizmet karması sabit varsayılıyor. İlk30 gün için dönüşüm bütçesi 1.200.000 TL ve en fazla 6 kişi-hafta uygulama kapasitesi var; günlük operasyon kapasitesi bu havuza dahil değil.'),
 doc('Aksiyon seçenekleri','Aylık faydalar birbirini dışlamayan tahminlerdir; aynı maliyetin iki aksiyonla azaltılması varsa bağımsızlık doğrulanmalı. Stok aksiyonu yalnız nakit serbestleştirir.',['ID','Aksiyon','Başlangıç nakdi TL','Tam uygulamada aylık sonuç etkisi TL','Kişi-hafta'],[['F','Fiyat%2; hacim sabit varsayımı',100000,200000,2],['T','Tedarik koşullarını iyileştir',0,150000,2],['S','Fazla stoktan nakit çıkar',50000,'500000 tek seferlik nakit girişi',1],['K','Yeniden işlemi azalt',200000,100000,3],['E','Yeni ERP',900000,'İlk3 ay fayda yok; ay6 sonrası belirsiz',8],['P','Yeni müşteri segmenti pilotu',250000,'Henüz ölçülmedi',3]]),
 doc('Karar ortamı','Tedarik kazancı kalite standardı düşürülmeden aranmalı. Stok satışı defter değerinden ve mevcut alıcıyla varsayılmıştır; gelir/kâr etkisi bu tabloda sıfırdır. ERP’nin 8 kişi-haftalık işi ilk 30 günde bölünmeden tamamlanacak kapsam olarak teklif edildi; bu kapsam kapasiteyi aşıyor. Fiyat/hacim tepkisi ve uygulamaya geçiş tarihleri belirsiz.')],
 ['Baz katkı ve faaliyet zararını hesapla; şirketin temel sorununu bir paragrafta çerçevele.','İlk30 gün için seçtiğin aksiyonların bütçe ve kişi-hafta toplamını göster; seçmediklerini gerekçelendir.','F/T/K’nin tam uygulama aylık etkisini ve ilk ayla farkını açıkla. S aksiyonunu kâr gibi göstermeden nakde bağla.','30/60/90 günlük plan hazırla: sorumlu, başlama önkoşulu, çıktı, kontrol göstergesi ve durdurma koşulu.','Yönetimden istediğin üç kararı ve henüz bilinmeyen kritik varsayımları yaz.'],[
 num('baz','Baz aylık faaliyet sonucu',-400000,'TL/ay',.1,'10.000.000−7.000.000−3.400.000=−400.000.'),num('stok','S aksiyonunun başlangıç gideri sonrası tek seferlik net nakit etkisi',450000,'TL',.1,'500.000 giriş−50.000 çıkış=450.000; aylık kâr artışı değildir.'),num('kapasite','F, T, S, K aksiyonlarının toplam ilk dönem kapasite ihtiyacı',8,'kişi-hafta',0,'2+2+1+3=8;6 kişi-hafta sınırını aşar. F/T/K bile 7 gerektirir.'),num('tam','F, T, K tam uygulanırsa baz varsayımlarla aylık faaliyet sonucu',50000,'TL/ay',.1,'−400.000+200.000+150.000+100.000=50.000. Fayda başlangıç tarihleri ve bağımsızlığı doğrulanmalıdır.')],
 [criterion('Sorunu ayrıştırma','Ciro, katkı, faaliyet zararı ve likiditeyi ayrı gösterir.'),criterion('Kaynak gerçekçiliği','İlk30 günün 6 kişi-hafta ve nakit sınırını aşmayan seçim yapar; hepsini eşzamanlı yazmaz.'),criterion('Fayda niteliği ve zaman','Stok nakdini aylık kâr saymaz; tam uygulama faydasını ilk ay gerçekleşmesi gibi sunmaz.'),criterion('Öncelik ve vazgeçiş','Seçilmeyen aksiyonların neden beklediğini ve hangi kanıtla öne alınacağını açıklar.'),criterion('Aksiyon planı','Sorumlu, önkoşul, ölçüt, tarih ve kontrol kapılarını bağlar.'),criterion('Duyarlılık','Fiyat/hacim, kalite ve fayda çakışması risklerini sınar; sonucu garanti etmez.')],
 {'title':'Fiyat sonrası hacim kaybı','text':'Fiyat%2 artınca hacim%3 düştü. Değişken gider hacimle orantılı, sabit gider aynı kaldı. F’nin aylık katkı iyileşmesi artık ne kadar? T/K tahminleri aynı kalsa şirket kâra geçer mi?','reference':'Satış 10.000.000×1,02×0,97=9.894.000; değişken gider 7.000.000×0,97=6.790.000; katkı 3.104.000 →104.000 iyileşme. T150.000 ve K100.000 ile toplam 354.000 iyileşir; şirket−46.000 TL/ayda kalır. F’nin 200.000 varsayımı korunamaz.'},
 ['Baz zarar 400.000 TL/ay. Stok aksiyonu 450.000 tek seferlik net nakit getirir, zarar modelini tek başına çözmez.','Örnek ilk dönem F/T/S:5 kişi-hafta ve150.000 başlangıç gideri; F+T tam uygulanınca 350.000/ay potansiyel iyileşme, kalan 50.000 zarar. F/K/S:6 kişi-hafta ve350.000 gider; 300.000/ay iyileşme. Bunlar tek geçerli seçim değildir.','Kritik uygulama ve kalite kapılarıyla sonraki dönemde kapsam genişletilebilir. ERP ilk 30 gün kapasitesine sığmaz, ilk 3 ay kâr çözümü değildir; stratejik değerini ayrı yol haritasında incelemek gerekir.'],
 ['Altı aksiyonu birden başlatıp kapasite hesabı yapmamak.','Stok satışını her ay tekrarlanan kâr artışı saymak.','Fiyat artışının hacmi hiç etkilemeyeceğini kesin kabul etmek.'],['Kâr getiren aksiyonun nakit etkisi gecikirse sıranı nasıl değiştirirsin?','Hangi iki faydanın aynı maliyet kalemini azalttığını nasıl kontrol edersin?'])
case('kapasite-ortakligi','Büyüyen talep: yatırım mı, ortaklık mı?',2,'Stratejik karar',50,['lead','operations','analyst','custom'],['Yap veya satın al','Geçiş modeli','Hizmet riski'],
'Bir hizmet işletmesi mevcut kapasitesinin üzerinde aylık 800 sipariş fırsatı görüyor. Talebin ne kadar kalıcı olduğu bilinmiyor. Kendi kapasitesini büyütme, iş ortağı kullanma ve geçici karma model seçeneklerini karşılaştıracaksın.',
'Sipariş başına 250 TL, yeni karşılama maliyeti öncesi katkıdır; satış geliri değildir. Aşağıdaki maliyetleri ayrıca düş. Uzun vadeli yatırım ile sekiz haftalık geçiş modelini aynı kalıcılıkta kabul etme.',[
 doc('Karşılama seçenekleri','Aylık 800 ek siparişin tamamının talep edildiği varsayılıyor. Yatırım tek seferliktir; aylık sabit giderler ek maliyetlerdir. Vergi, finansman, kurulum gecikmesi dahil değil.',['Model','Başlangıç TL','Kapasite sipariş/ay','Aylık sabit TL','Sipariş başı karşılama TL'],[['Kendi kapasitesi',2400000,1000,150000,60],['İş ortağı',200000,800,30000,140],['Karma geçiş',250000,800,35000,'600 sipariş×140;200 sipariş×90']]),
 doc('Uygulama koşulları','Karma modelde 200 siparişlik iç ek çalışma en fazla sekiz hafta için onaylanabilir; kalıcı çözüm değildir. İş ortağının hata/teslim performansı henüz pilotla doğrulanmadı. Kendi yatırımının başlama süresi ve siparişin devamlılığı belirsiz; ekip eğitimi gerekir.'),
 doc('Yönetim beklentisi','Yalnız en yüksek aylık farkı seçmek yerine hizmet standardı, bilgi güvenliği, müşteri etkisi, talebin düşmesi ve geri dönüş esnekliğini ele al. İlk aşamada sınırlı hacimli bir pilot veya erteleme önerebilirsin; bunun kaçan katkısını da açıkla.')],
 ['800 siparişte her seçeneğin ek aylık faaliyet sonucunu hesapla.','Başlangıç nakdi ve devamlılık koşullarını karşılaştır; karma modelin ne zaman bitmesi gerektiğini yaz.','Talep 400 siparişe düşerse kendi kapasitesi ile iş ortağını karşılaştır.','Bir ilk adım seç; iki alternatifi neden beklettiğini gerekçelendir.','Dört haftalık pilot için hizmet, kalite ve maliyet ölçütleriyle devam/durdurma kapısı kur.'],[
 num('kendi','800 siparişte kendi kapasitesinin aylık ek sonucu',2000,'TL/ay',.1,'800×(250−60)−150.000=2.000.'),num('ortak','800 siparişte iş ortağı modelinin aylık ek sonucu',58000,'TL/ay',.1,'800×(250−140)−30.000=58.000.'),num('karma','800 siparişte karma geçişin aylık ek sonucu',63000,'TL/ay',.1,'600×(250−140)+200×(250−90)−35.000=63.000; yalnız geçiş süresinde uygulanabilir.')],
 [criterion('Katkı tanımı','250 TL’yi satışla karıştırmaz; yeni birim ve sabit maliyetleri ayrıca düşer.'),criterion('Süre ve kapasite','Karma modelin sekiz haftalık sınırını ve kendi yatırımının başlangıç süresini ele alır.'),criterion('Talep duyarlılığı','Sabit maliyeti yüksek modelin düşük talepteki kaybını hesaplar.'),criterion('Operasyon ve müşteri riski','İş ortağı kalite, veri ve teslim koşullarını doğrulamadan ölçeklemez.'),criterion('Aşamalı öneri','Pilot, öğrenme, geçiş sonu ve kalıcı karar kapılarını bağlar.')],
 {'title':'Talep yarıya düştü','text':'Bir müşteri projeyi erteledi; ek talep 400 sipariş/ay. İş ortağının sabit/birim fiyatı aynı. Kendi kapasitesi yatırımının maliyetleri de değişmiyor. İki modelin aylık sonuçları ve seçimin nasıl değişir?','reference':'Kendi: 400×190−150.000=−74.000. İş ortağı: 400×110−30.000=14.000 TL/ay. Bu duyarlılık kalıcı yatırımın talep riskini gösterir; yatırımın başka doğrulanmış faydaları yokken bunları uydurup zararı kapatma.'},
 ['800 siparişte kendi 2.000, ortak 58.000, karma 63.000 TL/ay. Karma yalnız sekiz haftalık geçiştir; kalıcı en iyi model diye sunulamaz.','İş ortağıyla ölçülü pilot, düşük başlangıç ve daha düşük sabit yük nedeniyle savunulabilir. Ortak kalite riski veya veri koşulları kabul edilemiyorsa farklı öneri gerekebilir.','Kendi yatırımının kapasitesi 1.000 olsa da karşılığı olmayan 200 siparişi gerçekleşmiş kazanç sayma. Talep ve hizmet kanıtını yatırım kapısına bağla.'],
 ['250 TL katkıyı gelir sanıp bir kez daha ürün maliyeti düşmek.','Karma modeli sınırsız fazla çalışmayla sürekli hale getirmek.','Boş kapasiteyi kesin satış olarak yazmak.'],['İş ortağının hata oranı yükselirse hangi maliyetleri karşılaştırmaya eklersin?','Talep 1.000’i aşarsa hangi yeni veri gerekir?'])
case('musteri-toparlanma','Müşteri artıyor, şirket neden toparlanmıyor?',2,'Stratejik karar',50,['lead','analyst','custom'],['Müşteri kaybı','Katkı ve indirim','Kohort'],
'Bir abonelik işletmesi müşteri sayısını 1.000’den 1.100’e çıkardı ama hâlâ zarar ediyor. Satış her müşteriye indirim, hizmet ekibi ise hedefli elde tutma ve kalite iyileştirmesi öneriyor. Ekonomiyi ve öğrenme ihtiyacını birlikte ele alacaksın.',
'İlk müşteri kohortunun kaybını yeni kazanımla gizleme. Katkı ve indirim maliyetini tüm ilgili müşterilerde hesapla. Elde tutma tahminleri deney sonucu değil, senaryo varsayımıdır.',[
 doc('Aylık müşteri hareketi','Başlangıç kohortu 1.000 müşteri. Bunların 800’ü kaldı, 200’ü ayrıldı. 300 yeni müşteri eklendi; dönem sonunda 1.100 aktif müşteri var. Aktif müşteri başına aylık katkı 200 TL, sabit gider 260.000 TL varsayılmıştır. Yeni/eski müşteri katkısının eşitliği henüz doğrulanmadı.'),
 doc('Aksiyon seçenekleri','Aşağıdaki elde tutulan müşteri sayıları mevcut 1.100’e ek, kaybı önlendiği varsayılan müşterilerdir; tahminler çakışıyorsa fayda toplanamaz.',['Aksiyon','Ek tutulan müşteri','Gider kapsamı'],[['Herkese indirim',100,'Mevcut 1.100 ve ek100 müşterinin tamamına her ay50 TL'],['Hedefli çalışma',60,'Bir defalık 15000 TL; ek aylık gider yok varsayımı'],['Hizmet kalite desteği',80,'Her ay30000 TL; diğer kalite faydaları henüz ölçülmedi']]),
 doc('Değerlendirme ufku','İlk ay etkisini ve üç aylık etkiyi ayrı gösterebilirsin. Üç aylık hesapta ek tutulan müşterilerin her ay aktif ve katkısının aynı kaldığı varsayılmalı; bu kalıcılık doğrulanmadı. İndirim dışında katkı 200 TL/müşteri/ay sabittir. Kampanya yapılmasa da200 ayrılmanın sonraki ay aynen tekrarlanacağı kesin değildir.')],
 ['Başlangıç kohortunun kayıp oranını ve dönem sonu müşteri sayısını hesapla. Net büyümenin neyi gizlediğini açıkla.','Baz faaliyet sonucunu ve herkese indirim seçeneğinin ek aylık etkisini hesapla.','Hedefli çalışmayı ilk ay ve üç aylık varsayımsal ufukta değerlendir; baz zararı da göster.','Bir kontrollü deneme seç; karşılaştırma, süre, başarı/durdurma ölçütlerini tanımla.','Yönetim için “müşteri sayısı artışı” yerine birlikte takip edilecek dört gösterge öner.'],[
 num('kayip','Başlangıç kohortunun aylık müşteri kayıp oranı',20,'%',.05,'200/1.000×100=%20. Yeni 300 müşteri bu kohort kayıp oranının paydasına eklenmez.'),num('baz','Baz aylık faaliyet sonucu',-40000,'TL/ay',.1,'1.100×200−260.000=−40.000.'),num('indirim','Herkese indirim seçeneğinin baza göre ek aylık sonuç etkisi',-40000,'TL/ay',.1,'Ek100×200=20.000 katkı; 1.200 müşteriye×50=60.000 indirim; net−40.000. Yeni faaliyet sonucu−80.000 TL/ay.')],
 [criterion('Kohort ve büyüme','%20 eski müşteri kaybını%10 net büyümeyle karıştırmaz.'),criterion('Kapsamlı indirim maliyeti','İndirim alan 1.200 müşteriyi dahil eder; yalnız ek100’e maliyet yazmaz.'),criterion('Ufuk ve kalıcılık','Hedefli çalışmanın tek seferlik giderini ve çok aylık kalıcılık varsayımını ayırır.'),criterion('Nedensel kanıt','Elde tutulan müşteri tahminini kanıtlanmış etki saymaz; kontrollü ölçüm önerir.'),criterion('Toparlanma önerisi','Müşteri sayısı, katkı, kayıp ve nakit/kaliteyi birlikte izler; kâr açığının kaldığını gösterir.')],
 {'title':'Yeni müşteri katkısı farklı','text':'Yeni 300 müşterinin aylık katkısının 200 TL değil 100 TL olduğu anlaşıldı. Kalan eski 800 müşteride 200 TL geçerli. Baz faaliyet sonucunu ve büyüme yorumunu nasıl güncellersin?','reference':'800×200+300×100−260.000=−70.000 TL/ay. Baş sayısı artarken ortalama katkı düşebilir. Yeni kazanımla elde tutmayı aynı müşteri katkısıyla karşılaştırmak artık geçersizdir; aksiyonun hangi kohortu etkilediği ayrıştırılmalı.'},
 ['Eski kohort kaybı%20, net müşteri büyümesi%10. Biri diğerinin yerine geçmez. Baz zarar 40.000 TL/ay.','Herkese indirim, ek100’ün katkısını 20.000 artırırken toplam 60.000 indirim yaratır; baza göre 40.000 kötüleşir.','Hedefli çalışma ilk ay60×200−15.000=−3.000 ek etki, üç ayda 60×200×3−15.000=21.000 olumlu ek etki; üç aylık baz−120.000 zararı−99.000’e getirir, kalıcılık ve bağımsız etki varsayımıyla. Hizmet desteğinin yalnız verilen elde tutma faydası 16.000−30.000=−14.000/ay; diğer kalite faydaları ayrıca ölçülmeli.'],
 ['Ayrılan 200 kişiyi dönem sonu 1.100’e bölüp kohort kayıp oranı demek.','İndirimi yalnız ek tutulan 100 müşteri için hesaplamak.','Üç aylık müşteriyi kalıcı kabul edip yaşam boyu değer uydurmak.'],['Hedefli çalışmanın zaten kalacak müşterilere gittiğini nasıl fark edersin?','Kısa vadede olumsuz görünen kalite desteğinin uzun vadeli değerini nasıl sınarsın?'])
case('buyuk-musteri','Büyük sözleşme mi, dengeli müşteri portföyü mü?',3,'Stratejik karar',60,['lead','analyst','custom'],['Nakit ve kârlılık','Müşteri yoğunlaşması','Büyüme kararı'],
'Bir şirket yeni iş alanına girmek için iki fırsatı değerlendiriyor: büyük bir kurumsal müşteri veya daha küçük müşterilerden oluşan portföy. Büyük sözleşme daha yüksek aylık sonuç vaat ediyor, fakat ödeme vadesi uzun.',
'Kârlılık, ilk üç aylık fonlama ve müşteri yoğunlaşmasını birlikte değerlendir. Bu proje için ayrılmış nakit 4.000.000 TL ve korunacak rezerv 500.000 TL; mevcut işlerin nakdi bu tutarın dışında tutuldu. Tahsilat takvimini aylık varsayımla kullan, günlük dip ayrıca araştırılmalı.',[
 doc('İki yeni iş seçeneği','Başlangıç gideri faaliyetten önce ödenir. Değişken ve sabit giderler aynı ay ödenir; kapasite iki seçenek için de yeterli varsayılır. Vergi/finansman yoktur.',['Seçenek','Aylık satış TL','Katkı oranı %','Ek sabit gider TL/ay','Başlangıç nakdi TL'],[['Büyük sözleşme',2000000,25,180000,300000],['Küçük müşteri portföyü',1200000,35,160000,600000]]),
 doc('Tahsilat','Büyük sözleşmede ilk üç ay hiç tahsilat yok; ilk ödeme 4. ayda. Küçük müşteri portföyünde o ayki satışın%75’i aynı ay, kalan%25’i sonraki ay alınır. İlk ay önceden kalan alacak yoktur. Katkı oranı ürün/hizmet değişken gideri sonrası, ek sabit gider öncesidir.'),
 doc('Ticari risk ve yetki','Büyük seçenekte yeni işin tüm geliri tek müşteriye bağlıdır. Küçük portföy 40 müşteriden oluşur, en büyüğü bu portföy satışının%8’idir. Büyük sözleşmenin hacim garantisi ve erken fesih koşulları, küçük portföyün satış/servis kapasitesi henüz doğrulanmadı. Peşinat veya teminat için yetkili ticari müzakere gerekir.')],
 ['Her seçeneğin aylık faaliyet sonucunu hesapla; daha kârlı görüneni belirle.','Büyük sözleşmede ilk üç aylık nakit ihtiyacını ve rezervi koruyan ek fonlamayı hesapla.','Küçük portföyde başlangıç ve ilk ay sonunda kalan nakdi göster.','Yoğunlaşma, vade, fesih ve hizmet kapasitesi açısından bir seçenek ya da koşullu öneri sun.','Büyük müşteriyi seçebilmek için hangi ticari şartları değiştirmek istediğini ve karar kapılarını yaz.'],[
 num('buyuk_kar','Büyük sözleşmenin aylık faaliyet sonucu',320000,'TL/ay',.1,'2.000.000×0,25−180.000=320.000.'),num('kucuk_kar','Küçük portföyün aylık faaliyet sonucu',260000,'TL/ay',.1,'1.200.000×0,35−160.000=260.000.'),num('fon','Büyük sözleşmede ilk üç ay için rezerv dahil ek fonlama ihtiyacı',1840000,'TL',.1,'Aylık ödeme1.500.000+180.000=1.680.000;3ay5.040.000+başlangıç300.000+rezerv500.000−nakit4.000.000=1.840.000.'),num('kucuk_nakit','Küçük portföyde ilk ay sonu proje nakdi',3360000,'TL',.1,'4.000.000−600.000+900.000−(780.000+160.000)=3.360.000. İkinci aydan itibaren aynı varsayımlarda aylık 260.000 artış.')],
 [criterion('Kâr ve nakit','320.000 aylık kârın ilk üç ay nakit girişi olmadığını gösterir.'),criterion('Fonlama bütünü','Başlangıç, değişken/sabit ödeme ve500.000 rezervi birlikte hesaplar.'),criterion('Müşteri yoğunlaşması','Tek müşteriye bağımlılığı gelir büyüklüğüyle örtmez; fesih/taahhüt koşullarını ister.'),criterion('Koşullu karar','Peşinat, vade, aşamalı başlama ve finansman gibi müzakere seçeneklerini yetkili onayına bağlar.'),criterion('Küçük portföy gerçekçiliği','40 müşterinin edinim/hizmet yükünü ve tahsilat varsayımını doğrular.'),criterion('Karar sunumu','Alternatifleri aynı ufukta kıyaslar; fiyat veya vade değişirse önerinin nasıl değişeceğini açıklar.')],
 {'title':'%30 peşinat teklifi','text':'Büyük müşteri her ayın satışının%30’unu o ay ödemeyi kabul ediyor; kalan%70 için ilk tahsilat hâlâ 4. ayda. İlk üç ayda başlangıç ve500.000 rezerv dahil fonlama açığı kapanır mı?','reference':'İlk3ay peşinat 3×600.000=1.800.000. Önceki 1.840.000 ihtiyaca karşı hâlâ 40.000 TL açık var. Gün içi/hafta içi dip ve finansman giderleri de ayrıca incelenmeli. Aynı basit ufukta asgari peşinat 1.840.000/6.000.000≈%30,67 olur.'},
 ['Büyük 320.000, küçük 260.000 TL/ay faaliyet sonucu sağlar. Bu sıralama tek başına uygulanabilirlik kararı değildir.','Büyük seçenekte ilk 3ay ödemeler 5.040.000 ve başlangıç 300.000;4 milyon kaynak 500.000 rezervle 1.840.000 TL kısa kalır.','Küçük portföy ilk ay3.360.000 nakit bırakır ve baz vade varsayımıyla tamponu korur. Büyük seçenek ödeme/vade/finansman şartları değişirse savunulabilir; değişmiş şartların maliyeti yeniden hesaplanmalı.'],
 ['Tahakkuk eden kârı aynı ay nakit girişi saymak.','Başlangıç giderini veya rezervi fonlama hesabında unutmak.','%30 peşinatın ihtiyacı yaklaşık karşıladığını söyleyip 40.000 açığı yok saymak.'],['Büyük müşteri asgari hacim garantisi vermezse ne değişir?','Küçük müşterilerin tahsilatı da gecikirse hangi göstergeleri erken izlersin?'])
